"""Meridian CRM 4.2 RBAC permission semantics."""

from __future__ import annotations


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether ``user`` may perform ``action`` on ``record``.

    Permission rows are evaluated in their supplied order. Missing permission
    rows and unrecognized scopes deny access.
    """
    role_id = user.get("ROLE_ID", "")

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        # DELETE requires a record that is not already soft-deleted.
        # A blank or missing CHAR(1) boolean has legacy value 'N'.
        if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
            return False

        # ADMIN bypasses scope only when a matching permission row exists.
        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
        if scope == "OWN":
            return record.get("OWNER_UID", "") == user.get("USR_ID", "")
        if scope == "NONE":
            return False

        return False

    return False
